insert into public.news (slug,title,news_date,excerpt,category,image,url) values
('rejoignez-lequipe-des-ressources-humaines-de-la-bvmac-en-pos','Rejoignez l’équipe des Ressources Humaines de la BVMAC','2026-10-09','Nous recrutons un Ingénieur Support.','Recrutement','/photos/governance-group.webp','https://www.bvm-ac.org/actualites-bvmac-en/rejoignez-lequipe-des-ressources-humaines-de-la-bvmac-en-postulant-a-loffre-ci-apres/'),
('lancement-de-loperation-daugmentation-de-capital-par-appel-p','Lancement de l’opération d’augmentation de capital par appel public à l’épargne','2026-09-25','Une nouvelle opération d’augmentation de capital par appel public à l’épargne est ouverte sur le marché financier régional.','Marché','/photos/bvmac-building.webp','https://www.bvm-ac.org/actualites-bvmac-en/lancement-de-loperation-daugmentation-de-capital-par-appel-public-a-lepargne/'),
('emprunt-obligataire-par-appel-public-a-lepargne','Emprunt obligataire par appel public à l’épargne « EMF BAMBOO »','2026-07-27','Dans le cadre de son plan de développement stratégique, BAMBOO EMF S.A. envisage de mobiliser 5 milliards de francs CFA à travers l’émission obligataire « EMF BAMBOO ».','Marché','/photos/ceremony-arrival.webp','https://www.bvm-ac.org/actualites-bvmac-en/emprunt-obligataire-par-appel-public-a-lepargne/'),
('introduction-en-bourse-de-la-societe-bgfi-holding-corporatio','Introduction en bourse de la société BGFI Holding Corporation','2026-05-11','La BVMAC a procédé le 7 mai 2026 à la cérémonie officielle de première cotation des actions de BGFI Holding Corporation, la holding du Groupe BGFIBank, sur son compartiment A-Premium.','Événements','/photos/ceremony-speech.webp','https://www.bvm-ac.org/actualites-bvmac-en/introduction-en-bourse-de-la-societe-bgfi-holding-corporation/'),
('ceremonie-dintroduction-en-bourse-de-la-societe-bgfi-holding','Cérémonie d’introduction en bourse de la société BGFI Holding Corporation','2026-05-04','La cérémonie d’introduction en bourse de BGFI Holding Corporation se tiendra le jeudi 7 mai 2026 dès 9h30.','Événements','/photos/ceremony-speech.webp','https://www.bvm-ac.org/actualites-bvmac-en/ceremonie-dintroduction-en-bourse-de-la-societe-bgfi-holding-corporation/'),
('emprunt-obligataire-par-appel-public-a-lepargne-eog-2026-a-t','Emprunt obligataire « EOG 2026 à tranches multiples »','2026-03-02','Financez le développement, récoltez la croissance : 85 milliards FCFA, souscription du 25/02/2026 au 25/05/2026.','Marché','/photos/ceremony-guests.webp','https://www.bvm-ac.org/actualites-bvmac-en/emprunt-obligataire-par-appel-public-a-lepargne-eog-2026-a-tranches-multiples/'),
('la-bourse-des-valeurs-de-lafrique-centrale-lance-son-usine-a','La BVMAC lance son « usine à émetteurs » à Douala : BVMAC ESPro','2026-02-20','Le 3 février 2026, devant un parterre de chefs d’entreprise et d’institutions financières, la BVMAC a officiellement présenté BVMAC ESPro, son programme d’accompagnement des futurs émetteurs.','Institutionnel','/photos/ceremony-talk.webp','https://www.bvm-ac.org/actualites-bvmac-en/la-bourse-des-valeurs-de-lafrique-centrale-lance-son-usine-a-emetteurs-a-douala-bvmac-espro/'),
('introduction-en-bourse-de-la-reserve-nationale-de-lepargne-e','Introduction en bourse de la Réserve Nationale de l’Épargne et de la Provision (RENAPROV)','2025-12-30','Montant de l’émission : 8 400 000 000 FCFA. Souscription du 15/12/2025 au 15/03/2026. Prix de l’action : 21 000 FCFA.','Marché','/photos/ceremony-audience.webp','https://www.bvm-ac.org/actualites-bvmac-en/introduction-en-bourse-de-la-reserve-nationale-de-lepargne-et-de-la-provision-renaprov/'),
('emprunt-obligataire-par-appel-public-a-lepargne-eog-2025-a-t','Emprunt obligataire « EOG 2025 à tranches multiples 2 »','2025-09-15','Investir aujourd’hui pour bâtir l’avenir : 50 milliards FCFA levés par l’État gabonais.','Marché','/photos/ceremony-trading-floor-2.webp','https://www.bvm-ac.org/actualites-bvmac-en/emprunt-obligataire-par-appel-public-a-lepargne-eog-2025-a-tranches-multiples-2/'),
('eog-multi-tranches-2024-2030-premiere-cotation-de-nouvelles','Première cotation de nouvelles obligations du Gabon « EOG multi-tranches 2024-2030 »','2025-07-11','La salle des marchés de la bourse unifiée de la CEMAC a abrité la cérémonie de première cotation de nouvelles obligations de l’État gabonais.','Événements','/photos/ceremony-trading-floor.webp','https://www.bvm-ac.org/actualites-bvmac-en/eog-multi-tranches-2024-2030-premiere-cotation-de-nouvelles-obligations-du-gabon/'),
('ceremonie-de-premiere-cotation-des-obligations-souveraines-d','Cérémonie de première cotation des obligations souveraines de l’État du Gabon « EOG multi-tranches 2024-2030 II »','2025-05-23','La BVMAC porte à la connaissance du public la cérémonie de première cotation des obligations souveraines de l’État du Gabon.','Événements','/photos/ceremony-handshake.webp','https://www.bvm-ac.org/actualites-bvmac-en/ceremonie-de-premiere-cotation-des-obligations-souveraines-de-letat-du-gabon-eog-multi-tranches-2024-2030-ii/')
